INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (4100710, 10071003, "boss_def_lower_limit", "バトル開始時、すべてのモンスターの物理防御力をアップさせる。この効果は物理防御力ダウンの影響を受けない。", "物理防御力（ダウン不可）アップ");
INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (4100710, 10071004, "boss_magic_def_lower_limit", "バトル開始時、すべてのモンスターの魔法防御力をアップさせる。この効果は魔法防御力ダウンの影響を受けない。", "魔法防御力（ダウン不可）アップ");
INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (4100710, 10071005, "boss_tp_down_cut", "バトル開始時、すべてのモンスターがＴＰダウン\n75％カット状態になる。", "ＴＰダウンカット");
INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (4100710, 10071006, 3, "バトル開始時、すべてのキャラのＴＰ上昇をダウンさせる。", "ＴＰ上昇ダウン");
INSERT INTO `v1_b0098477468fb655b7130dacc54f4b4dd3c80f0c3247b86802be6efa54a7c73d` VALUES (4100710, 10071007, 9, "バトル開始時、すべてのキャラのＨＰ吸収をダウンさせる。", "ＨＰ吸収ダウン");
